<script setup lang="ts">import {onMounted,ref} from 'vue';import {useRoute} from 'vue-router';const route=useRoute(),item=ref<any>();onMounted(async()=>{const r=await fetch(`/api/admin/shipments/${route.params.id}`,{headers:{Authorization:`Bearer ${localStorage.getItem('token')}`}});if(r.ok)item.value=await r.json()})</script>
<template><section v-if="item" class="card"><RouterLink to="/admin/billing">← Vissza</RouterLink><h1>{{item.masterTrackingNumber||'Szállítmány'}}</h1><p>{{item.company}} · {{item.productCode}} · {{item.status}}</p><p>DHL: {{item.dhlEstimatedCost}} · Ügyfél: {{item.customerPrice}} · Árrés: {{item.margin}}</p><div v-for="p in item.packages" :key="p.packageIndex" class="package">{{p.packageIndex}}. csomag — {{p.weight}} kg, {{p.length}}×{{p.width}}×{{p.height}} cm — {{p.trackingNumber}}</div><a v-for="l in item.labels" :key="l.id" :href="`/api/shipments/${item.id}/labels/${l.id}`">{{l.fileName}}</a></section><p v-else>Betöltés…</p></template>
